const SDK = window.__OIKOS_SDK__;
const React = SDK.React.default ?? SDK.React;
const { useCardConfig, useDashboard, useStyles, MdiIcon } = SDK;
const h = React.createElement;

const DEF={alarmEntity:'alarm_control_panel.alarmo',garageEntity:'cover.portone_garage',guestEntity:'input_boolean.modalita_ospite'};
function labelAlarm(s){return ({disarmed:'Disinserito',armed_home:'Casa',armed_night:'Notte',armed_away:'Assente',triggered:'ALLARME'})[s]||s||'—';}
function labelGarage(s){return ({closed:'Chiuso',open:'Aperto',opening:'Apertura',closing:'Chiusura'})[s]||s||'—';}
function tile(s,icon,title,value,accent,click){return h('button',{type:'button',onClick:click,style:{minHeight:110,borderRadius:s.tokens.radius.lg,padding:s.tokens.space.md,background:'var(--bg-secondary)',border:'1px solid var(--border-subtle,rgba(255,255,255,.08))',color:s.tokens.color.primary,display:'flex',flexDirection:'column',justifyContent:'space-between',alignItems:'flex-start',cursor:'pointer',textAlign:'left'}},h('div',{style:{width:42,height:42,borderRadius:s.tokens.radius.md,display:'flex',alignItems:'center',justifyContent:'center',background:`color-mix(in srgb, ${accent} 13%, transparent)`}},h(MdiIcon,{name:icon,size:23,color:accent})),h('div',null,h('div',{style:{...s.title,fontSize:15}},title),h('div',{style:{...s.hint,color:accent}},value)));}
export default function Card({cardId='casa-es-overview'}){const s=useStyles();const d=useDashboard();const [c]=useCardConfig(cardId,DEF);const alarm=d.getState(c.alarmEntity),garage=d.getState(c.garageEntity),guest=d.getState(c.guestEntity);const toggleGuest=()=>d.callService('input_boolean',guest==='on'?'turn_off':'turn_on',c.guestEntity);return h('div',{style:{...s.card,display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(130px,1fr))',gap:s.tokens.space.sm}},tile(s,'mdi:shield-home','Sicurezza',labelAlarm(alarm),alarm==='triggered'?'#ff453a':alarm==='disarmed'?s.tokens.color.green:s.tokens.color.amber,()=>d.openMoreInfo(c.alarmEntity)),tile(s,'mdi:garage','Garage',labelGarage(garage),garage==='closed'?s.tokens.color.green:s.tokens.color.amber,()=>d.openMoreInfo(c.garageEntity)),tile(s,'mdi:account-star','Ospiti',guest==='on'?'Attivo':'Spento',guest==='on'?s.tokens.color.purple:s.tokens.color.muted,toggleGuest));}
